import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, TierDto } from './create-dimension.dto.js';

@ValidatorConstraint({ name: 'TierValidationRule', async: false })
@Injectable()
export class TierValidationRule implements ValidatorConstraintInterface {
    validate(tiers: TierDto[], args: ValidationArguments) {
        if (!tiers || tiers.length === 0) {
            return true;
        }

        const dto = args.object as CreateDimensionDto;
        const usageIncrement = parseInt(dto.usageIncrement, 10);

        if (isNaN(usageIncrement) || usageIncrement <= 0) {
            return false;
        }

        const sortedTiers = [...tiers].sort((a, b) => parseInt(a.tierPosition, 10) - parseInt(b.tierPosition, 10));

        for (let i = 0; i < sortedTiers.length; i++) {
            const tier = sortedTiers[i];
            const position = parseInt(tier.tierPosition, 10);

            if (isNaN(position) || position !== i + 1) {
                return false;
            }

            const upperBound = tier.upperBound;
            if (upperBound !== 'inf') {
                const boundValue = parseFloat(upperBound);
                if (isNaN(boundValue) || boundValue <= 0) {
                    return false;
                }
                if (boundValue % usageIncrement !== 0) {
                    return false;
                }
            } else if (i !== sortedTiers.length - 1) {
                return false;
            }

            if (i > 0) {
                const prevTier = sortedTiers[i - 1];
                const prevBound = prevTier.upperBound;
                if (prevBound === 'inf') {
                    return false;
                }
                const prevBoundValue = parseFloat(prevBound);
                const currBoundValue = upperBound === 'inf' ? Infinity : parseFloat(upperBound);
                if (currBoundValue <= prevBoundValue) {
                    return false;
                }
            }

            if (i > 0 && (!tier.unitPrice || tier.unitPrice.trim() === '')) {
                return false;
            }

            if (i === 0 && tier.unitPrice !== undefined && tier.unitPrice !== '' && isNaN(parseFloat(tier.unitPrice))) {
                return false;
            }

            if (tier.unitPrice !== undefined && tier.unitPrice !== '') {
                const price = parseFloat(tier.unitPrice);
                if (isNaN(price)) {
                    return false;
                }
            }
        }

        if (dto.usageEntitlement !== undefined && dto.usageEntitlement !== null) {
            return false;
        }
        if (dto.consumptionPrice !== undefined && dto.consumptionPrice !== null && dto.consumptionPrice !== '') {
            return false;
        }
        if (dto.overageAllowed === 'true') {
            return false;
        }

        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const dto = args.object as CreateDimensionDto;
        const usageIncrement = parseInt(dto.usageIncrement, 10);
        return `Invalid tiers configuration: tierPosition must be sequential starting from 1; upperBound must be numeric string or "inf" (only allowed on last tier); bounds must strictly increase and align to usageIncrement (${usageIncrement}); all tiers except first must have unitPrice; tiers are mutually exclusive with usageEntitlement, consumptionPrice, and overageAllowed: true`;
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TierValidationRule,
        });
    };
}

@ValidatorConstraint({ name: 'TierMutualExclusivityRule', async: false })
@Injectable()
export class TierMutualExclusivityRule implements ValidatorConstraintInterface {
    validate(value: unknown, args: ValidationArguments) {
        const dto = args.object as CreateDimensionDto;
        const hasTiers = dto.tiers && dto.tiers.length > 0;

        if (!hasTiers) {
            return true;
        }

        if (dto.usageEntitlement !== undefined && dto.usageEntitlement !== null) {
            return false;
        }
        if (dto.consumptionPrice !== undefined && dto.consumptionPrice !== null && dto.consumptionPrice !== '') {
            return false;
        }
        if (dto.overageAllowed === 'true') {
            return false;
        }

        return true;
    }

    defaultMessage() {
        return 'Tiers are mutually exclusive with usageEntitlement, consumptionPrice, and overageAllowed: true';
    }
}

export function TierMutualExclusivity(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'TierMutualExclusivity',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TierMutualExclusivityRule,
        });
    };
}

