static async getLineItemsForUsage({
        startDate,
        endDate,
        customer,
        lineItems,
        negative,
        businessID,
        customerId,
        customerService,
        dimensions,
        offeringInstance,
    }: {
        startDate: Date;
        endDate: Date;
        customer?: ReadCustomerResponseData;
        lineItems: InvoiceLineItems;
        negative?: boolean;
        businessID: string;
        customerId: string;
        customerService: CustomerService;
        dimensions: ReadOfferingResponseData['dimensions'];
        offeringInstance: Offering;
    }): Promise<InvoiceLineItems> {
        const usage = await customerService.findUsageForCustomer(
            {
                businessID,
                customerId,
                customer,
            },
            {
                startTime: startDate.toISOString(),
                endTime: endDate.toISOString(),
            },
        );

        const aggregateUsageData = usage?.data as AggregatedUsageResponse[];

        const dimensionMap = dimensions.reduce((acc, dimension) => {
            acc[dimension.dimensionId] = dimension;
            return acc;
        }, {}) as Record<string, ReadDimensionResponseData>;
        const dimensionTotals = aggregateUsageData.reduce((acc, usageElement) => {
            const { dimensionId } = usageElement;

            const total = Billing.usageToTotal(usageElement, dimensionMap[dimensionId]);

            if (acc[dimensionId]) {
                acc[dimensionId] += parseFloat(total);
                acc[dimensionId] = acc[dimensionId].toFixed(2);
            } else {
                acc[dimensionId] = parseFloat(total);
                acc[dimensionId] = acc[dimensionId].toFixed(2);
            }

            return acc;
        }, {}) as Record<string, number>;
        let exchangeRate = 1;

        if (Offering.getCurrency({ customer, offering: offeringInstance }) !== SupportedCurrencies.USD) {
            console.log('Inside exchange rate');
            exchangeRate = await AnalyticsService.getExchangeRate({
                currency: Offering.getCurrency({ customer, offering: offeringInstance }),
            });
            lineItems.addTerms(
                `Invoice dynamically calculated with realtime currency exchange rate €${exchangeRate.toFixed(
                    2,
                )} = $1.00`,
            );
        }

        Object.keys(dimensionTotals).forEach((dimensionId) => {
            const dimension = dimensionMap[dimensionId];
            const totalUsage = dimensionTotals[dimensionId] as number;

            if (dimension.tiers && dimension.tiers.length > 0) {
                Offering.addTieredLineItems({
                    dimension,
                    totalUsage,
                    lineItems,
                    exchangeRate,
                    negative,
                    offeringName: offeringInstance.offeringName,
                });
            } else {
                const unitCost = Number(
                    (parseFloat(dimension.consumptionPrice) * exchangeRate).toFixed(
                        Offering.getDecimalsForNumber(parseFloat(dimension.consumptionPrice)) === 0
                            ? 2
                            : Offering.getDecimalsForNumber(parseFloat(dimension.consumptionPrice)),
                    ),
                );
                const shouldDisplayLineItem = Billing.determineIfLineItemShown({
                    Offering: offeringInstance,
                    dimension,
                    totalUsage,
                    unitCost,
                    freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
                });
                if (shouldDisplayLineItem) {
                    const {
                        usageIncrement,
                        consumptionUnit: { unit, type },
                    } = dimension;
                    const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                        total: totalUsage,
                        dimensionType: type,
                        dimensionId,
                        dimensionName: dimension.dimensionName,
                        offeringName: offeringInstance.offeringName,
                        usageIncrement: parseInt(usageIncrement),
                        dimensionUnit: unit,
                        negative,
                    });
                    lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
                }
            }
        });

        return lineItems;
    }

    private static addTieredLineItems({
        dimension,
        totalUsage,
        lineItems,
        exchangeRate,
        negative,
        offeringName,
    }: {
        dimension: ReadDimensionResponseData;
        totalUsage: number;
        lineItems: InvoiceLineItems;
        exchangeRate: number;
        negative?: boolean;
        offeringName: string;
    }): void {
        const tiers = [...dimension.tiers].sort((a, b) => parseInt(a.tierPosition, 10) - parseInt(b.tierPosition, 10));
        const usageIncrement = parseInt(dimension.usageIncrement, 10);
        const { unit, type } = dimension.consumptionUnit;

        let remainingUsage = totalUsage;
        let previousBound = 0;

        for (const tier of tiers) {
            if (remainingUsage <= 0) {
                break;
            }

            const upperBound = tier.upperBound === 'inf' ? Infinity : parseFloat(tier.upperBound);
            const tierCapacity = upperBound - previousBound;

            if (tierCapacity <= 0) {
                previousBound = upperBound;
                continue;
            }

            const tierUsage = Math.min(remainingUsage, tierCapacity);
            if (tierUsage <= 0) {
                previousBound = upperBound;
                continue;
            }

            const unitPrice = tier.unitPrice ? parseFloat(tier.unitPrice) : 0;
            const unitCost = Number(
                (unitPrice * exchangeRate).toFixed(
                    Offering.getDecimalsForNumber(unitPrice) === 0 ? 2 : Offering.getDecimalsForNumber(unitPrice),
                ),
            );

            const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
                total: tierUsage,
                dimensionType: type,
                dimensionId: dimension.dimensionId,
                dimensionName: dimension.dimensionName,
                offeringName: offeringName,
                usageIncrement,
                dimensionUnit: unit,
                negative,
            });

            const tierDisplayName = tier.tierName ? `${displayName} - ${tier.tierName}` : displayName;
            lineItems.addLineItem(new InvoiceLineItem(tierDisplayName, displayTotal, unitCost));

            remainingUsage -= tierUsage;
            previousBound = upperBound;
        }
    }

